function findSubstring(s: string, words: string[]): number[] {
  const wordLen = words[0].length;
  const wordCount = words.length;
  const totalLen = wordLen * wordCount;
  const result: number[] = [];
  if (s.length < totalLen) return result;

  // Сколько раз каждое слово должно встретиться в окне
  const need = new Map<string, number>();
  for (const w of words) need.set(w, (need.get(w) ?? 0) + 1);

  // Режем s на слова с разными сдвигами: 0, 1, ..., wordLen - 1.
  // Для каждого сдвига запускаем отдельное скользящее окно по «словам»
  for (let offset = 0; offset < wordLen; offset++) {
    const window = new Map<string, number>(); // слова внутри окна
    let left = offset; // начало окна
    let count = 0; // сколько слов сейчас в окне

    for (let right = offset; right + wordLen <= s.length; right += wordLen) {
      const word = s.slice(right, right + wordLen);

      if (!need.has(word)) {
        // Чужое слово рвёт любую конкатенацию — начинаем окно заново после него
        window.clear();
        count = 0;
        left = right + wordLen;
        continue;
      }

      window.set(word, (window.get(word) ?? 0) + 1);
      count++;

      // Слово встретилось чаще, чем нужно — сужаем окно слева
      while (window.get(word)! > need.get(word)!) {
        const leftWord = s.slice(left, left + wordLen);
        window.set(leftWord, window.get(leftWord)! - 1);
        count--;
        left += wordLen;
      }

      // В окне ровно все слова — нашли ответ
      if (count === wordCount) {
        result.push(left);
        // Сдвигаем окно на одно слово, чтобы искать дальше
        const leftWord = s.slice(left, left + wordLen);
        window.set(leftWord, window.get(leftWord)! - 1);
        count--;
        left += wordLen;
      }
    }
  }

  return result;
}

// Время: O(n · wordLen) — для каждого из wordLen сдвигов проходим строку,
//        каждое слово входит в окно и выходит из него один раз
// Память: O(m) — карты частот слов (m — число слов)
